  private static func decode(_ value: Any, _ b: TokamakBinding, as type: CLLocationCoordinate2D.Type) throws -> CLLocationCoordinate2D {
    try CLLocationCoordinate2D(
      latitude: b.decode(b.field(value, "latitude"), as: CLLocationDegrees.self),
      longitude: b.decode(b.field(value, "longitude"), as: CLLocationDegrees.self)
    )
  }
}
